from pathlib import Path
from pprint import pformat

from poke_env.data import GenData


def generate_type_chart():
    chart = GenData(9).type_chart
    output = Path(__file__).parent.parent / "src" / "agent" / "type_chart.py"
    output.write_text(
        "# generated by scripts/generate_type_chart.py\n"
        "# TYPE_CHART[defender_type][move_type] -> damage multiplier\n"
        f"TYPE_CHART: dict[str, dict[str, float]] = {pformat(chart)}\n"
    )


if __name__ == "__main__":
    generate_type_chart()
